void* worker_routine(void* arg_data) {
    // Standard signature: void* (*start_routine)(void*)

    // Cast and retrieve input data passed via pthread_create
    int* shared_value = (int*)arg_data;

    if (shared_value != NULL) {
        (*shared_value) += 10;
    }

    // Define the return status/result (must be void*)
    int status = 0;

    // Return or exit
    // pthread_exit((void*)(intptr_t)status);
    return (void*)(intptr_t)status;
}
